#pragma once
/* isim simd for C and Objective-C (issue #800; generated by tools/simd-headers.py): Apple's <simd/base.h> names over clang vector extensions,
 * header-only like Apple's. The functions are overloadable static inlines; Swift uses its own simd module, so they are
 * hidden from Swift (the types are not). */
#define SIMD_COMPILER_HAS_REQUIRED_FEATURES 1
#define SIMD_OVERLOAD __attribute__((__overloadable__))
#define SIMD_CFUNC static inline __attribute__((__overloadable__, __always_inline__, __nodebug__))
#define SIMD_NOINLINE static __attribute__((__overloadable__, __noinline__))
#define SIMD_CONST __attribute__((__const__))
#if defined(__swift__)
#define __ISIM_SIMD_FUNCTIONS 0
#else
#define __ISIM_SIMD_FUNCTIONS 1
#endif
